const prompt="Edit this exact minimal eight-tree atlas. Preserve ALL tree silhouettes, 4 columns x 2 rows layout, solid low-contrast olive colors, 2–3 large crown planes, tiny trunks, no extra detail. ONLY ADD A CLEAR SIMPLE GROUND SHADOW beneath EVERY tree. Shadow is a small FLAT muted darker olive silhouette (#56613a) attached to the base and extending towards LOWER LEFT, representing light from upper RIGHT. It must be visibly distinct from the crown's own dark color plane, and visible beside/behind the trunk on the ground. About 20–30% of the canopy width, short compact oval/irregular shape, no giant dark disk, no glow, NO blur, no soft halo. Keep the background otherwise truly transparent. Entire tree AND new shadow must stay within its cell with generous empty gutters. Do not add leaf scallops, branches, highlights, outlines or texture. Do not change the minimal style or make contrast harsher.";
store("treeshadowprompt",prompt);const r=await tools.image_gen__imagegen({prompt,referenced_image_paths:["/home/suselman/.codex/generated_images/01a12b71-bbfc-7011-a8f7-86fa6646b384/exec-6f02f10c-dbf8-40b3-81c7-e4f05eaa12b2.png"],transparent_background:true});store("treeshadowgen",r);if(r.output_hint)text(r.output_hint);

// @exec: {"yield_time_ms": 1000, "max_output_tokens": 1000}
const specs=[
["rockshadowgen","/home/suselman/projects/hearthvale/assets/rocks-v1.png","Edit this exact eight-stone 4x2 atlas. Preserve every irregular stone pile, flat gray-brown/cream colors and golden vein markings, minimal detail and overhead orthographic camera. ONLY ADD A VISIBLE COMPACT GROUND SHADOW to every pile. Shadow is a flat muted dark olive-gray shape (#56613a), attached to the rock's lower-left base, extending 20–30% of the pile width towards LOWER LEFT. Light from upper RIGHT. The ground shadow must be clearly visible outside the rock silhouette, not merely a darker front face. No blurry halo no glow no gradient. Keep transparent empty background, generous gutters, whole pile and shadow inside its cell. Do not increase stone facets or add any decoration, outline, letters or background."],
["wildlifeshadowgen","/home/suselman/projects/hearthvale/assets/hunting-v1.png","Edit this exact 2x2 sprite atlas. Preserve the cute little deer in top-left, white rabbit top-right and both hunters bottom row, their silhouettes, colors, proportions and cell positions. Add a VISIBLE SHORT SIMPLE GROUND SHADOW beneath the feet of ALL FOUR sprites, especially deer and rabbit. Flat muted olive shadow (#56613a), attached to ground contact and extending towards LOWER LEFT, light from upper RIGHT. Compact irregular oval, no glow, no blur, no broad colored aura. Shadows must be separate from the characters' darker body planes and remain inside cell. Genuine transparent empty background and clean cell gutters. Do not alter the animal faces, hunter designs, add textures, text, border or scene. Keep simple matte raster style."],
["berrybushgen","/home/suselman/projects/hearthvale/assets/berries-v1.png","Generate a NEW 4-column x 2-row atlas of berry BUSHES ONLY using the input's palette/style but much simpler. Top row four distinct small low bushes: one wide irregular crown, one simple round crown, one two-mass crown, one asymmetric crown. Each crown only TWO OR THREE LARGE SOLID FLAT olive color shapes (#737b38 main, #626c35 shadow, #848d45 highlight), no tiny scallops, no leaf spots, no noise. On each top-row bush just 3–5 small red berry dots, simple opaque red circles, no glossy highlights. Bottom row EXACTLY THE SAME four bushes in same positions and sizes but WITHOUT BERRIES, used after harvest. Every bush has a mandatory visible short flat olive ground shadow extending LOWER LEFT from its base, light upper RIGHT, no blur/glow. Camera orthographic almost directly overhead 15 degrees FROM VERTICAL, zero perspective and no side rotation, very short stems. Tiny uncomplicated minimalist game objects, consistent scale, generous transparent gutters, entirely inside equal cells. No people, huts, icons, text or scenery. True transparent background, clean silhouettes."]
];
await Promise.all(specs.map(async([key,path,prompt])=>{store(key+"prompt",prompt);const r=await tools.image_gen__imagegen({prompt,referenced_image_paths:[path],transparent_background:true});store(key,r);if(r.output_hint)text({key,hint:r.output_hint});}));

